                    print(prefix+'  case', i, c.get('value'), 'inputs?', len(c.get('inputs',[])))
                    walk(c['inputs'], prefix+'    ')
            if 'inputs' in x:
                walk(x['inputs'], prefix+'  ')
        else:
            print(prefix, 'DICT key', x.get('name'), x.get('model_class'), 'label=',x.get('label'), 'value=',str(x.get('value'))[:200])
    elif isinstance(x, list):
        for i,item in enumerate(x):
            print(prefix+f'[{i}]')
            walk(item, prefix+'  ')
    else:
        print(prefix, repr(x)[:200])
walk(data['inputs'])
