        name=x.get('name')
        mc=x.get('model_class')
        if mc in ('Repeat',) or name in ('archives','label','archive','filter_suffix'):
            print('PATH', path, 'model', mc, 'name', name, 'label', x.get('label'), 'value', json.dumps(x.get('value'))[:300])
        if 'inputs' in x:
            for i,ch in enumerate(x['inputs']):
                walk(ch, path+'/'+str(name or mc)+'['+str(i)+']')
        if 'cases' in x:
            for i,c in enumerate(x['cases']):
                # print case value
                walk(c, path+'/case['+str(c.get('value'))+']')
    elif isinstance(x, list):
        for i,item in enumerate(x): walk(item, path+'['+str(i)+']')
walk(data['inputs'])
PY"
